const fs = require('fs');
const backupPath = '/backups';

const dbInfo = $('Consultar Tamaño DB Postgres').first().json || {};
const dbPretty = dbInfo.db_size_pretty || 'desconocido';
const dbBytes = Number(dbInfo.db_size_bytes || 0);

const issuesResp = $('Consultar Incidencias MantisBT').first().json || {};
const openIssues = (issuesResp.issues || []).filter(i => {
  const st = (i.status?.name || '').toLowerCase();
  return st !== 'resolved' && st !== 'closed';
});

// Buscar si ya existe una incidencia de backup abierta
const existingIssue = openIssues.find(i => {
  const s = (i.summary || '').toLowerCase();
  const d = (i.description || '').toLowerCase();
  return s.includes('backup') || d.includes('backup');
});

let isBackupValid = false;
let failureReasons = [];
let latestFile = 'N/A';
let fileSizeMB = '0';
let fileSizeBytes = 0;
let fileAgeHours = '999';
let headerFormat = 'UNKNOWN';
let totalBackupsCount = 0;
let totalStorageMB = '0';

try {
  if (fs.existsSync(backupPath)) {
    const allFiles = fs.readdirSync(backupPath);
    const backupFiles = allFiles.filter(f => f.endsWith('.dump') || f.endsWith('.sql'));
    totalBackupsCount = backupFiles.length;

    if (backupFiles.length > 0) {
      let totalBytes = 0;
      const stats = backupFiles.map(file => {
        try {
          const stat = fs.statSync(`${backupPath}/${file}`);
          totalBytes += stat.size;
          return { file, mtime: stat.mtime, size: stat.size };
        } catch (e) {
          return { file, mtime: new Date(0), size: 0 };
        }
      }).sort((a, b) => b.mtime - a.mtime);

      totalStorageMB = (totalBytes / (1024 * 1024)).toFixed(2);
      const latest = stats[0];
      latestFile = latest.file;
      fileSizeBytes = latest.size;
      fileSizeMB = (latest.size / (1024 * 1024)).toFixed(2);
      fileAgeHours = ((new Date() - new Date(latest.mtime)) / (1000 * 60 * 60)).toFixed(2);

      // 1. Verificación de antigüedad (RPO <= 25 horas)
      if (parseFloat(fileAgeHours) > 25) {
        failureReasons.push(`Antigüedad excesiva: ${fileAgeHours}hs (límite RPO: 25hs)`);
      }

      // 2. Verificación de tamaño mínimo no vacío
      if (latest.size <= 512) {
        failureReasons.push(`Archivo sospechosamente pequeño o vacío: ${latest.size} bytes`);
      }

      // 3. Verificación de Integridad de Cabecera Binaria (Magic Bytes)
      try {
        const fd = fs.openSync(`${backupPath}/${latestFile}`, 'r');
        const buf = Buffer.alloc(8);
        fs.readSync(fd, buf, 0, 8, 0);
        fs.closeSync(fd);
        const asciiHeader = buf.toString('ascii');

        if (latestFile.endsWith('.dump')) {
          if (asciiHeader.startsWith('PGDMP')) {
            headerFormat = 'PostgreSQL Custom Dump (PGDMP - Válido)';
          } else {
            headerFormat = 'Formato no reconocido';
            failureReasons.push('Cabecera corrupta o inválida (no inicia con magic bytes PGDMP)');
          }
        } else if (latestFile.endsWith('.sql')) {
          headerFormat = 'SQL Plain Text';
          if (!asciiHeader.includes('--') && !asciiHeader.includes('/*') && !asciiHeader.toLowerCase().includes('set')) {
            failureReasons.push('Archivo SQL sin estructura estándar de PostgreSQL');
          }
        }
      } catch (errHeader) {
        failureReasons.push(`Error al leer cabecera binaria: ${errHeader.message}`);
      }

      if (failureReasons.length === 0) {
        isBackupValid = true;
      }
    } else {
      failureReasons.push('No se encontraron copias (.dump / .sql) en /backups');
    }
  } else {
    failureReasons.push('Directorio /backups no existe o no está montado');
  }
} catch (err) {
  failureReasons.push(`Excepción de sistema de archivos: ${err.message}`);
}

let action = '';
let status = '';
let statusSummary = '';
let detailedReport = '';

const dateIso = new Date().toISOString();
const grafanaUrl = 'http://localhost:3000/d/observabilidad-integral/observabilidad-integral?from=now-1h&to=now';

if (isBackupValid) {
  if (existingIssue) {
    action = 'RESOLVE';
    status = 'RESOLVED';
    statusSummary = `[RECUPERADO] Backup de PostgreSQL verificado exitosamente`;
    detailedReport = `[AUTO-RECUPERACIÓN] La verificación de copias de seguridad de PostgreSQL se ha normalizado a las ${dateIso}.\nArchivo verificado: ${latestFile}\nTamaño: ${fileSizeMB} MB | Formato: ${headerFormat}\nAntigüedad: ${fileAgeHours}hs\nTamaño base de datos viva: ${dbPretty}\nTotal copias en almacén: ${totalBackupsCount} (${totalStorageMB} MB)`;
  } else {
    action = 'SUCCESS';
    status = 'SUCCESS';
    statusSummary = `Backup verificado correctamente: ${latestFile} (${fileSizeMB} MB, hace ${fileAgeHours}hs)`;
    detailedReport = `Verificación periódica exitosa. Archivo: ${latestFile} (${fileSizeMB} MB, cabecera ${headerFormat}). BD soderia: ${dbPretty}. Copias totales: ${totalBackupsCount}.`;
  }
} else {
  if (existingIssue) {
    action = 'DEDUP_NOTE';
    status = 'DEDUP_NOTE';
    statusSummary = `[REINCIDENCIA] Fallo continuo en verificación de backups de PostgreSQL`;
    detailedReport = `[SEGUIMIENTO AUTOMÁTICO] La anomalía en los backups de PostgreSQL continúa activa a las ${dateIso}.\nMotivos detectados:\n- ${failureReasons.join('\n- ')}\nÚltimo archivo detectado: ${latestFile} (${fileSizeMB} MB)\nTamaño actual de la BD soderia: ${dbPretty}`;
  } else {
    action = 'CREATE';
    status = 'FAILED';
    statusSummary = `[CRITICAL] Fallo en verificación de backups de PostgreSQL`;
    detailedReport = [
      '====================================================',
      ' ALERTA DE CONTINUIDAD DE NEGOCIO: BACKUPS POSTGRESQL',
      '====================================================',
      `Estado          : FALLO DE INTEGRIDAD / RPO`,
      `Fecha Chequeo   : ${dateIso}`,
      `Último Archivo  : ${latestFile}`,
      `Tamaño Copia    : ${fileSizeMB} MB`,
      `Antigüedad      : ${fileAgeHours} horas`,
      `Cabecera / Tipo : ${headerFormat}`,
      `Tamaño BD Real  : ${dbPretty} (${dbBytes} bytes)`,
      `Copias en Disco : ${totalBackupsCount} (${totalStorageMB} MB)`,
      '----------------------------------------------------',
      ' ANOMALÍAS DETECTADAS:',
      `- ${failureReasons.join('\n- ')}`,
      '----------------------------------------------------',
      `Acción Requerida: Ejecutar manual 'docker compose run --rm backup' y revisar servicio backup.`,
      'Origen          : n8n Workflow 02 / Auditoría Automatizada'
    ].join('\n');
  }
}

return [{
  json: {
    isBackupValid,
    action,
    status,
    statusSummary,
    detailedReport,
    latestFile,
    fileSizeMB,
    fileAgeHours,
    headerFormat,
    totalBackupsCount,
    totalStorageMB,
    dbPretty,
    failureReasons: failureReasons.join('; '),
    issueId: existingIssue ? existingIssue.id : null,
    grafanaUrl,
    alertname: 'PostgresBackupVerification',
    severity: isBackupValid ? 'info' : 'critical',
    mantisPriority: 'urgent',
    mantisSeverity: 'major'
  }
}];

